/* Noir — EcomStrait Liquid theme. Dark canvas is fixed in layout/theme.liquid;
   brand/accent, fonts and radius come from theme settings. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font-body);color:var(--ink);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;object-fit:cover}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--font-heading);line-height:1.15;margin:0;font-weight:400}
.muted{color:var(--muted)}
.container{width:100%;max-width:1240px;margin:0 auto;padding:0 24px}
.section{padding:80px 0}
.section--narrow{max-width:720px;margin:0 auto}
.section-title{font-size:clamp(1.7rem,3vw,2.4rem);letter-spacing:-.01em}
.section-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:36px;padding-bottom:18px;border-bottom:1px solid var(--line)}
.link-more{color:var(--brand);font-size:.72rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em;white-space:nowrap}
.link-more:hover{color:var(--ink)}

/* Buttons — squared, uppercase, letterspaced */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border:1px solid transparent;cursor:pointer;font-family:var(--font-body);font-weight:600;font-size:.74rem;text-transform:uppercase;letter-spacing:.16em;padding:.95rem 1.7rem;border-radius:var(--radius);transition:background-color .25s ease,color .25s ease,border-color .25s ease}
.btn-lg{padding:1.1rem 2.4rem}
.btn-primary{background:var(--brand);color:#0B0B0C;border-color:var(--brand)}
.btn-primary:hover{background:transparent;color:var(--brand)}
.btn-primary[disabled]{opacity:.4;cursor:not-allowed;background:transparent;color:var(--muted);border-color:var(--line)}
.btn-ghost{background:transparent;border-color:var(--line);color:var(--ink)}
.btn-ghost:hover{border-color:var(--ink)}

/* Header */
.site-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.site-header__inner{display:flex;align-items:center;justify-content:space-between;gap:32px;height:76px}
.site-header__name{font-family:var(--font-heading);font-size:1.35rem;letter-spacing:.14em;text-transform:uppercase}
.site-nav{display:flex;gap:32px}
.site-nav__link{position:relative;font-size:.74rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em;color:var(--muted);padding:4px 0}
.site-nav__link::after{content:"";position:absolute;left:0;right:100%;bottom:0;height:1px;background:var(--brand);transition:right .3s ease}
.site-nav__link:hover,.site-nav__link.is-active{color:var(--ink)}
.site-nav__link:hover::after,.site-nav__link.is-active::after{right:0}
.site-header__cart{font-size:.74rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em}
.cart-count{display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:var(--brand);color:#0B0B0C;font-size:.68rem;letter-spacing:0}
@media (max-width:640px){.site-nav{display:none}.site-header__inner{height:64px}}

/* Hero — full-bleed, editorial */
.hero{position:relative;background:var(--surface);background-size:cover;background-position:center;border-bottom:1px solid var(--line)}
.hero__inner{padding:132px 24px;text-align:center;max-width:800px;margin:0 auto}
.hero__rule{display:block;width:56px;height:1px;background:var(--brand);margin:0 auto 32px}
.hero__heading{font-size:clamp(2.2rem,5.5vw,4rem);letter-spacing:-.015em}
.hero__subheading{font-size:clamp(.98rem,1.6vw,1.12rem);color:var(--muted);margin:22px auto 40px;max-width:56ch}
.hero--image .hero__inner{padding:176px 24px}
@media (max-width:640px){.hero__inner,.hero--image .hero__inner{padding:88px 24px}}

/* Grids */
.grid{display:grid;gap:28px}
.grid-products{grid-template-columns:repeat(2,1fr)}
.grid-collections{grid-template-columns:repeat(2,1fr)}
.grid-3{grid-template-columns:repeat(3,1fr)}
@media (min-width:720px){.grid-products{grid-template-columns:repeat(4,1fr)}.grid-collections{grid-template-columns:repeat(3,1fr)}}
@media (max-width:640px){.grid-3{grid-template-columns:1fr}}

/* Product card — image-led, no boxy border */
.product-card{display:flex;flex-direction:column;overflow:hidden;background:transparent}
.product-card__media{position:relative;aspect-ratio:3/4;overflow:hidden;background:var(--surface)}
.product-card__media img{width:100%;height:100%;transition:transform .6s cubic-bezier(.22,.61,.36,1)}
.product-card:hover .product-card__media img{transform:scale(1.05)}
.product-card__placeholder,.product-card--placeholder{aspect-ratio:3/4;background:linear-gradient(160deg,var(--surface),var(--surface-2))}
.product-card__body{padding:16px 2px 0;display:flex;flex-direction:column;gap:6px}
.product-card__title{font-size:.92rem;color:var(--ink)}
.product-card__price{font-size:.88rem;font-weight:600;color:var(--brand);letter-spacing:.02em}
.badge{position:absolute;top:14px;left:14px;padding:5px 11px;font-size:.62rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em}
.badge--soldout{background:var(--bg);color:var(--ink);border:1px solid var(--line)}
.price--sale .price__was{color:var(--muted);margin-right:8px;font-weight:400}

/* Product page */
.product{display:grid;grid-template-columns:1.1fr 1fr;gap:64px;align-items:start}
@media (max-width:820px){.product{grid-template-columns:1fr;gap:36px}}
.product__media img{background:var(--surface)}
.product__title{font-size:clamp(1.8rem,3vw,2.6rem);letter-spacing:-.01em}
.product__price{font-size:1.2rem;font-weight:600;color:var(--brand);margin:16px 0 32px;padding-bottom:28px;border-bottom:1px solid var(--line)}
.product__options{display:flex;flex-wrap:wrap;gap:18px;margin-bottom:26px}
.product__option{display:flex;flex-direction:column;gap:8px;font-size:.7rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.product__option select{padding:.7rem .9rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body);font-size:.9rem;letter-spacing:0;text-transform:none}
.product__option select:focus-visible{outline:1px solid var(--brand);outline-offset:1px}
.product__description{margin-top:36px;padding-top:28px;border-top:1px solid var(--line);color:var(--muted)}
.product__media-placeholder{aspect-ratio:1/1;background:linear-gradient(160deg,var(--surface),var(--surface-2))}

/* Value props */
.value-props{border-top:1px solid var(--line)}
.value-prop{padding:34px 28px;background:var(--surface);border-radius:var(--radius)}
.value-prop__title{font-size:.76rem;font-weight:600;font-family:var(--font-body);text-transform:uppercase;letter-spacing:.18em;color:var(--brand);margin-bottom:12px}

/* Cart */
.cart-line{display:grid;grid-template-columns:80px 1fr auto auto;gap:20px;align-items:center;padding:22px 0;border-bottom:1px solid var(--line)}
.cart-line__title{font-size:.95rem}
.cart-line__qty{width:68px;padding:.6rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body)}
.cart-footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:20px;align-items:center;padding-top:28px}
.cart-subtotal{display:flex;align-items:baseline;gap:14px;font-size:.76rem;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.cart-subtotal strong{font-family:var(--font-heading);font-size:1.5rem;font-weight:400;letter-spacing:0;color:var(--brand);text-transform:none}
.cart-actions{display:flex;gap:14px}

/* Collections */
.collection-card{position:relative;display:block;overflow:hidden;background:var(--surface)}
.collection-card img{transition:transform .6s cubic-bezier(.22,.61,.36,1)}
.collection-card:hover img{transform:scale(1.04)}
.collection-card__title{position:absolute;left:0;right:0;bottom:0;padding:20px;background:linear-gradient(180deg,transparent,rgba(11,11,12,.85));font-size:.76rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em}
.collection-head{margin-bottom:36px;padding-bottom:18px;border-bottom:1px solid var(--line)}

/* Misc */
.rte a{color:var(--brand);text-decoration:underline;text-underline-offset:3px}
.pagination{display:flex;gap:18px;justify-content:center;margin-top:48px;font-size:.8rem;color:var(--muted)}
.pagination a:hover{color:var(--ink)}
.pagination .is-current{color:var(--brand)}
.search-form{display:flex;gap:12px;margin:24px 0 36px}
.search-form input{flex:1;padding:.9rem 1.1rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body)}
.search-form input::placeholder{color:var(--muted)}
.search-form input:focus-visible{outline:1px solid var(--brand);outline-offset:1px}
:focus-visible{outline:1px solid var(--brand);outline-offset:2px}

/* Footer */
.site-footer{margin-top:64px;border-top:1px solid var(--line);padding:56px 0 32px;background:var(--surface)}
.site-footer__inner{display:flex;flex-wrap:wrap;justify-content:space-between;gap:32px}
.site-footer__name{font-family:var(--font-heading);font-size:1.2rem;letter-spacing:.14em;text-transform:uppercase;margin:0 0 8px}
.site-footer__nav{display:flex;flex-direction:column;gap:12px;font-size:.8rem;color:var(--muted)}
.site-footer__nav a:hover{color:var(--ink)}
.site-footer__legal{margin-top:40px;padding-top:24px;border-top:1px solid var(--line);font-size:.74rem;letter-spacing:.06em}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

/* --- EcomStrait content blocks --- */
.announcement-bar{background:var(--brand);color:#fff;text-align:center;font-size:.82rem;font-weight:600;padding:.55rem 1rem}
.hero{position:relative;overflow:hidden}
.hero__video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0}
.hero__scrim{position:absolute;inset:0;background:rgba(0,0,0,.45);z-index:1}
.hero__inner{position:relative;z-index:2}
.about-section{padding:3rem 0}
.about-section__inner{display:grid;gap:2rem;align-items:center}
@media(min-width:760px){.about-section__inner{grid-template-columns:1fr 1fr}}
.about-section__media{width:100%;height:auto;object-fit:cover;border-radius:var(--radius)}
.es-block{padding:2.5rem 0}
.es-block__heading{text-align:center;margin:0 0 1.2rem}
.es-block__body{max-width:44rem;margin:0 auto;text-align:center}
.es-grid{display:grid;gap:1.25rem}
@media(min-width:700px){.es-grid--3{grid-template-columns:repeat(3,1fr)}.es-grid--4{grid-template-columns:repeat(4,1fr)}.es-split{grid-template-columns:1fr 1fr}}
.es-media{width:100%;height:auto;object-fit:cover;border-radius:var(--radius);display:block}
.es-media--square{aspect-ratio:1}

/* ===== Storefront foundation =====================================
   Navigation, category grid, the sidebar collection page and the product
   gallery. Written against the theme tokens only (--brand/--ink/--bg/
   --surface/--line/--muted/--radius/--font-*), so each theme keeps its own
   palette, type and corner treatment without a variant of this block. */

.visually-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.nav-locked{overflow:hidden}

/* Header additions */
.site-header__actions{display:flex;align-items:center;gap:18px}
.site-header__icon{display:grid;place-items:center;width:22px;height:22px;color:var(--ink);opacity:.75}
.site-header__icon:hover{opacity:1}
.site-header__icon svg{width:20px;height:20px}

/* Desktop dropdown. focus-within as well as hover, so it opens on Tab. */
.site-nav__group{position:relative}
.site-nav__caret{display:inline-block;width:0;height:0;margin-left:6px;vertical-align:middle;border-left:4px solid transparent;border-right:4px solid transparent;border-top:4px solid currentColor;opacity:.7}
.site-nav__menu{position:absolute;top:100%;left:0;min-width:200px;padding:10px 0;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);box-shadow:0 18px 40px -24px rgba(0,0,0,.45);opacity:0;visibility:hidden;transform:translateY(6px);transition:opacity .18s ease,transform .18s ease,visibility .18s;z-index:30}
.site-nav__group:hover .site-nav__menu,.site-nav__group:focus-within .site-nav__menu{opacity:1;visibility:visible;transform:translateY(0)}
.site-nav__menu-link{display:block;padding:8px 18px;font-size:.86rem;color:var(--muted);white-space:nowrap}
.site-nav__menu-link:hover{color:var(--ink);background:var(--surface)}

/* Mobile menu. The button is hidden on desktop, not removed, so the drawer
   stays available to anyone who resizes down. */
.nav-toggle{display:none;flex-direction:column;justify-content:center;gap:5px;width:40px;height:40px;padding:0 9px;background:none;border:0;cursor:pointer;color:var(--ink)}
.nav-toggle__bar{display:block;height:1.5px;width:100%;background:currentColor;transition:transform .2s ease,opacity .2s ease}
.nav-toggle[aria-expanded="true"] .nav-toggle__bar:nth-child(1){transform:translateY(6.5px) rotate(45deg)}
.nav-toggle[aria-expanded="true"] .nav-toggle__bar:nth-child(2){opacity:0}
.nav-toggle[aria-expanded="true"] .nav-toggle__bar:nth-child(3){transform:translateY(-6.5px) rotate(-45deg)}

.nav-drawer{position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.45);opacity:0;visibility:hidden;transition:opacity .25s ease,visibility .25s}
.nav-drawer.is-open{opacity:1;visibility:visible}
.nav-drawer__panel{position:absolute;inset:0 auto 0 0;display:flex;flex-direction:column;width:min(86vw,340px);padding:22px;background:var(--bg);border-right:1px solid var(--line);transform:translateX(-100%);transition:transform .28s cubic-bezier(.22,.61,.36,1);overflow-y:auto}
.nav-drawer.is-open .nav-drawer__panel{transform:translateX(0)}
.nav-drawer__head{display:flex;align-items:center;justify-content:space-between;padding-bottom:18px;margin-bottom:10px;border-bottom:1px solid var(--line)}
.nav-drawer__title{font-family:var(--font-heading);font-size:1.05rem}
.nav-drawer__close{background:none;border:0;font-size:1.9rem;line-height:1;color:var(--ink);cursor:pointer}
.nav-drawer__nav{display:flex;flex-direction:column}
.nav-drawer__link{padding:13px 0;font-size:1rem;color:var(--ink);border-bottom:1px solid var(--line)}
.nav-drawer__link--child{padding-left:16px;font-size:.9rem;color:var(--muted)}

@media (max-width:900px){
  .site-nav{display:none}
  .nav-toggle{display:flex}
  .site-header__cart-label{display:none}
}

/* Category grid */
.collection-card__placeholder{display:block;aspect-ratio:7/5;background:linear-gradient(150deg,var(--surface),color-mix(in srgb,var(--brand) 14%,var(--surface)))}
.collection-card__count{display:block;margin-top:4px;font-size:.68rem;font-weight:400;letter-spacing:.1em;opacity:.75}

/* Collection header + breadcrumb */
.collection-hero{padding:38px 0 30px;border-bottom:1px solid var(--line);background:var(--surface)}
.collection-hero__title{font-family:var(--font-heading);font-size:clamp(1.7rem,3.4vw,2.6rem);margin:10px 0 0}
.collection-hero__copy{max-width:62ch;margin-top:12px}
.breadcrumb{display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:.74rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.breadcrumb a:hover{color:var(--ink)}
.breadcrumb [aria-current]{color:var(--ink)}

/* Two-column collection page: categories and filters left, products right. */
.collection-layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:44px;align-items:start}
@media (max-width:900px){.collection-layout{grid-template-columns:1fr;gap:28px}}

.collection-aside{position:sticky;top:96px;display:flex;flex-direction:column;gap:26px}
@media (max-width:900px){.collection-aside{position:static;gap:20px}}
.collection-aside__block{display:flex;flex-direction:column;gap:10px}
.collection-aside__title{font-size:.72rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em;color:var(--muted);margin:0}
.collection-aside__form{display:flex;flex-direction:column;gap:26px}
.collection-aside__apply{align-self:flex-start}
.collection-aside__clear{font-size:.78rem;color:var(--brand);text-decoration:underline;text-underline-offset:3px}

.category-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.category-list__link{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 0;font-size:.92rem;color:var(--muted);border-bottom:1px solid var(--line)}
.category-list__link:hover{color:var(--ink)}
.category-list__link.is-active{color:var(--brand);font-weight:600}
.category-list__count{font-size:.72rem;opacity:.6}

.filter-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:7px}
.filter-list__item{display:flex;align-items:center;gap:9px;font-size:.9rem;color:var(--ink);cursor:pointer}
.filter-list__item.is-empty{opacity:.4;cursor:not-allowed}
.filter-list__item input{accent-color:var(--brand);width:15px;height:15px}
.filter-list__count{margin-left:auto;font-size:.72rem;color:var(--muted)}

.field{width:100%;padding:.6rem .7rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body);font-size:.9rem}
.field:focus-visible{outline:1px solid var(--brand);outline-offset:1px}
.price-filter{display:flex;align-items:center;gap:8px}
.price-filter__field{flex:1;min-width:0}
.price-filter__dash{color:var(--muted)}

.collection-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:16px;margin-bottom:22px;border-bottom:1px solid var(--line)}
.collection-toolbar__count{margin:0;font-size:.8rem}
.collection-empty{padding:56px 0;text-align:center;display:flex;flex-direction:column;align-items:center;gap:16px}

/* Product gallery + buy row */
.product__vendor{margin:0 0 8px;font-size:.72rem;font-weight:600;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.product__thumbs{display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:10px;margin-top:12px}
.product__thumb{padding:0;background:none;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;cursor:pointer;transition:border-color .18s ease}
.product__thumb img{aspect-ratio:1;width:100%;object-fit:cover}
.product__thumb:hover{border-color:var(--muted)}
.product__thumb.is-active{border-color:var(--brand)}
.product__buy{display:flex;flex-wrap:wrap;align-items:stretch;gap:12px;margin-bottom:8px}
.product__add{flex:1;min-width:180px}
.qty{display:flex;align-items:center;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}
.qty__step{width:38px;background:none;border:0;color:var(--ink);font-size:1rem;cursor:pointer}
.qty__step:hover{background:var(--surface)}
.qty input{width:46px;padding:.7rem 0;text-align:center;background:none;border:0;color:var(--ink);font-family:var(--font-body);-moz-appearance:textfield}
.qty input::-webkit-outer-spin-button,.qty input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}

/* Noir: the drawer and dropdown sit on the raised surface, never on the page
   black, or they read as holes rather than panels. Sidebar type matches the
   theme's letterspaced uppercase. */
.site-nav__menu,.nav-drawer__panel{background:var(--surface-2);border-color:var(--line)}
.site-nav__menu{box-shadow:0 24px 60px -30px #000}
.category-list__link{font-size:.78rem;text-transform:uppercase;letter-spacing:.12em}
.category-list__link.is-active{font-weight:600}
.collection-hero{background:var(--surface)}
.collection-hero__title{letter-spacing:-.01em}
.product__thumb.is-active{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand)}

/* ===== Noir: luxury house ========================================
   The centred wordmark over a centred rule of navigation is the oldest
   signal a fashion house has. Categories become two large portrait
   plates rather than a row of thumbnails, and the product gallery runs
   as a vertical rail so the main image stays the biggest thing on screen. */
.site-header__inner{display:grid;grid-template-areas:"toggle brand actions" "nav nav nav";grid-template-columns:1fr auto 1fr;row-gap:14px;height:auto;padding-top:20px;padding-bottom:16px}
.nav-toggle{grid-area:toggle;justify-self:start}
.site-header__logo{grid-area:brand;justify-self:center}
.site-header__actions{grid-area:actions;justify-self:end}
.site-nav{grid-area:nav;justify-content:center;padding-top:12px;border-top:1px solid var(--line)}
.site-header__name{font-size:1.7rem;letter-spacing:.3em}
@media (max-width:900px){.site-header__inner{grid-template-areas:"toggle brand actions";row-gap:0;padding-top:0;padding-bottom:0}}

.grid-collections{grid-template-columns:repeat(2,1fr);gap:2px}
@media (max-width:720px){.grid-collections{grid-template-columns:1fr}}
.collection-card img,.collection-card__placeholder{aspect-ratio:4/5}
.collection-card__title{padding:28px 26px;font-size:.8rem;letter-spacing:.24em;background:linear-gradient(180deg,transparent,rgba(11,11,12,.92))}
.collection-card__count{letter-spacing:.16em;font-size:.62rem;opacity:.65}

.collection-layout{grid-template-columns:210px minmax(0,1fr);gap:60px}
.collection-main .grid-products{grid-template-columns:repeat(3,1fr);gap:34px}
@media (max-width:820px){.collection-main .grid-products{grid-template-columns:repeat(2,1fr)}}

/* Thumbnails as a left rail — the plate stays dominant. */
.product{grid-template-columns:1.25fr 1fr;gap:70px}
.product__media{display:grid;grid-template-columns:72px minmax(0,1fr);gap:14px;align-items:start}
.product__media .product__image,.product__media-placeholder{grid-column:2;grid-row:1}
.product__thumbs{grid-column:1;grid-row:1;display:flex;flex-direction:column;gap:10px;margin-top:0}
@media (max-width:820px){.product{grid-template-columns:1fr}.product__media{grid-template-columns:1fr}.product__media .product__image,.product__media-placeholder{grid-column:1}.product__thumbs{grid-column:1;grid-row:2;flex-direction:row;flex-wrap:wrap}}

/* Two-up portrait plates ran to ~875px tall on a wide screen — imposing is
   the intent, a full viewport of one category is not. Landscape at a capped
   height keeps the drama and lets the second row register. */
.grid-collections{align-items:start}
.collection-card img,.collection-card__placeholder{aspect-ratio:3/2;max-height:440px}

/* Capping the height without pinning the width let aspect-ratio shrink the
   image sideways, exposing a sliver of card behind it. Explicit width keeps
   the plate full-bleed and lets object-fit crop vertically instead. */
.collection-card img,.collection-card__placeholder{width:100%;object-fit:cover}

/* ===== Responsive re-assertion ===================================
   The per-theme layout rules above were written unconditionally, and
   because they sit later in the file they overrode the media queries
   that came before them. The collection page kept its fixed sidebar
   column at every width — 210-260px plus a 32-72px gutter inside a
   390px screen — which pushed the whole page wider than the viewport
   and clipped the right-hand edge. Same for the product split.

   These come last so a narrow viewport genuinely wins. Any future
   layout rule must be added ABOVE this block, or it will reintroduce
   the same bug. */
@media (max-width:900px){
  .collection-layout{grid-template-columns:minmax(0,1fr);gap:26px}
  .collection-aside{position:static}
  .collection-aside__form{gap:20px}
}
@media (max-width:820px){
  .product{grid-template-columns:minmax(0,1fr);gap:32px}
}
@media (max-width:640px){
  .grid-collections{grid-template-columns:minmax(0,1fr)}
  .grid-products,.collection-main .grid-products{grid-template-columns:repeat(2,minmax(0,1fr))}
  .collection-hero{padding:24px 0 20px}
  .product__buy{flex-direction:column}
  .product__add{width:100%}
}

/* `.section-head` is a space-between row holding a large heading and a
   nowrap "view all" link. Their combined min-content width is wider than a
   phone, so the link overflowed the container and dragged a horizontal
   scrollbar across the whole page — the visible symptom being a clipped
   "ALL CATEGORI…" and every section sitting a few pixels too far right. */
@media (max-width:640px){
  .section-head{flex-wrap:wrap;align-items:flex-start;gap:10px}
  .link-more{white-space:normal}
  .breadcrumb{font-size:.68rem}
}

assets/theme.js:
/**
 * EcomStrait theme behaviour.
 *
 * Everything here is progressive: the markup works without it (links navigate,
 * forms submit, the first variant is selectable), and this makes it pleasant.
 * The one exception is the mobile menu, which is genuinely unreachable without
 * JS — so the toggle button is rendered by this file rather than sitting inert
 * in the markup for people who never get it.
 *
 * No framework and no build step. It is served as a plain asset and parsed
 * before anything renders, so it stays small and dependency-free on purpose.
 */
(function () {
  "use strict";

  var on = function (el, ev, fn) { if (el) el.addEventListener(ev, fn); };
  var $ = function (sel, root) { return (root || document).querySelector(sel); };
  var $$ = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };

  /* ---------------------------------------------------------------- nav --
   * The drawer is a sibling of the header rather than a child, so a sticky
   * header with backdrop-filter doesn't become its containing block and trap
   * the overlay behind it.
   */
  function initNav() {
    var toggle = $("[data-nav-toggle]");
    var drawer = $("[data-nav-drawer]");
    if (!toggle || !drawer) return;

    var close = function () {
      drawer.classList.remove("is-open");
      toggle.setAttribute("aria-expanded", "false");
      document.documentElement.classList.remove("nav-locked");
    };
    var open = function () {
      drawer.classList.add("is-open");
      toggle.setAttribute("aria-expanded", "true");
      // Scroll lock on <html>: iOS ignores overflow:hidden on <body> alone.
      document.documentElement.classList.add("nav-locked");
      var first = drawer.querySelector("a, button");
      if (first) first.focus();
    };

    on(toggle, "click", function () {
      if (drawer.classList.contains("is-open")) close(); else open();
    });
    on($("[data-nav-close]"), "click", close);
    on(drawer, "click", function (e) { if (e.target === drawer) close(); });
    on(document, "keydown", function (e) { if (e.key === "Escape") close(); });
  }

  /* ------------------------------------------------------------ variants --
   * Without this the option selects are decorative: the form posts whatever
   * variant id was rendered server-side, so picking "Large / Blue" adds the
   * small red one. The selects carry the option position so the lookup does
   * not depend on their order in the DOM.
   */
  function initVariants() {
    var root = $("[data-product]");
    if (!root) return;
    var data = $("[data-variants]", root);
    if (!data) return;

    var variants;
    try { variants = JSON.parse(data.textContent); } catch { return; }
    if (!variants || !variants.length) return;

    var selects = $$("[data-option-index]", root);
    var idInput = $("[data-variant-id]", root);
    var button = $("[data-add-button]", root);
    var priceEl = $("[data-price]", root);
    var mainImg = $("[data-gallery-main]", root);

    function match() {
      var chosen = [];
      selects.forEach(function (s) { chosen[parseInt(s.dataset.optionIndex, 10)] = s.value; });
      for (var i = 0; i < variants.length; i++) {
        var v = variants[i], ok = true;
        for (var j = 0; j < chosen.length; j++) {
          if (chosen[j] !== undefined && v.options[j] !== chosen[j]) { ok = false; break; }
        }
        if (ok) return v;
      }
      return null;
    }

    function apply() {
      var v = match();
      // No such combination: disable rather than silently adding something
      // else. A shopper told "unavailable" can try another size; one who
      // receives the wrong variant finds out after it ships.
      if (!v) {
        if (button) { button.disabled = true; button.textContent = "Unavailable"; }
        return;
      }
      if (idInput) idInput.value = v.id;
      if (button) {
        button.disabled = !v.available;
        button.textContent = v.available ? button.dataset.labelAdd : button.dataset.labelSoldOut;
      }
      if (priceEl && v.price_formatted) priceEl.innerHTML = v.price_formatted;
      if (mainImg && v.image) { mainImg.src = v.image; mainImg.srcset = ""; }
    }

    selects.forEach(function (s) { on(s, "change", apply); });
    apply();
  }

  /* ------------------------------------------------------------- gallery --
   * Thumbnails swap the main image. Plain <img> swapping rather than a slider:
   * it needs no library, keeps every image in the DOM for crawlers, and
   * degrades to a column of images if this never runs.
   */
  function initGallery() {
    var main = $("[data-gallery-main]");
    if (!main) return;
    var thumbs = $$("[data-gallery-thumb]");
    if (thumbs.length < 2) return;

    thumbs.forEach(function (btn) {
      on(btn, "click", function () {
        main.src = btn.dataset.full || btn.dataset.src;
        main.srcset = "";
        main.alt = btn.dataset.alt || main.alt;
        thumbs.forEach(function (t) { t.classList.remove("is-active"); t.setAttribute("aria-current", "false"); });
        btn.classList.add("is-active");
        btn.setAttribute("aria-current", "true");
      });
    });
  }

  /* ------------------------------------------------------------ quantity -- */
  function initQuantity() {
    $$("[data-qty]").forEach(function (wrap) {
      var input = $("input", wrap);
      if (!input) return;
      $$("[data-qty-step]", wrap).forEach(function (btn) {
        on(btn, "click", function () {
          var next = (parseInt(input.value, 10) || 1) + parseInt(btn.dataset.qtyStep, 10);
          input.value = Math.max(1, next);
          input.dispatchEvent(new Event("change", { bubbles: true }));
        });
      });
    });
  }

  /* ------------------------------------------------------------- filters --
   * The sidebar is a real GET form, so it works submitted. With JS, changing a
   * control submits immediately, which is what shoppers expect from a filter.
   * The Apply button is removed here rather than hidden in CSS, so it is still
   * there for anyone this script never reaches.
   */
  function initFilters() {
    var form = $("[data-filter-form]");
    if (!form) return;
    $$("select, input[type=checkbox]", form).forEach(function (el) {
      on(el, "change", function () { form.submit(); });
    });
    var apply = $("[data-filter-apply]", form);
    if (apply) apply.remove();
  }

  function init() {
    initNav();
    initVariants();
    initGallery();
    initQuantity();
    initFilters();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

